insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('supply', 'beginner', 'module', 'm01-what-a-terminal-measures', 1, 'terminalDepot exports 8 functions and 0 constants. What does that 0 tell you about where a strapping table, a correction coefficient and an opening stock come from?', '["They live in fuelPricing, whose 8 constants the tank calls read.", "They are built into the functions as defaults, so none is counted.", "None of them lives in the module, so each one arrives from the terminal that owns the tank.", "They sit in PRODUCT_REFERENCE, which each of the tank calls reads first."]'::jsonb, 2, 'terminalDepot exports 8 functions and 0 constants, so no table, coefficient or opening stock ships inside it. volumeAtDip refuses with no strapping table, volumeCorrectionFactor refuses with no coefficients and reconcileStock refuses with no opening stock. PRODUCT_REFERENCE is read only when a caller passes one of its densities in.'),
  ('supply', 'beginner', 'module', 'm01-what-a-terminal-measures', 2, 'Which two of fuelPricing''s constants each hold a single number?', '["LITRES_PER_M3 and M3_PER_BBL", "IMPORT_TEMPLATE and PUMP_TEMPLATE", "PRODUCT_REFERENCE and CHARGE_BASIS", "RATE_DISCLAIMER and PRODUCT_REFERENCE"]'::jsonb, 0, 'LITRES_PER_M3 reads 1000 and M3_PER_BBL reads 0.158987294928. IMPORT_TEMPLATE and PUMP_TEMPLATE are tables of line items with every rate absent, CHARGE_BASIS is a list of bases, RATE_DISCLAIMER is a sentence and PRODUCT_REFERENCE is a table of typical densities.'),
  ('supply', 'beginner', 'module', 'm01-what-a-terminal-measures', 3, 'dipToStandardVolume is called on AK-01 with its dip, its water cut and its table, and with no volume correction factor. What does the engine answer?', '["REFUSED, because a tank call with no volume correction factor forms no figure of any kind", "gross 3461.489 m3 and standard 3461.489 m3, the missing factor taken as exactly one", "gross 3461.489 m3 and standard 0.000 m3, the blank factor read as zero", "gross 3461.489 m3 and standard none, with a note that only the gross observed volume is reported"]'::jsonb, 3, 'The engine walks the chain as far as the measured inputs reach. The gross observed volume, 3461.489 m3, needs no VCF, so it prints; the standard volume reads none.'),
  ('supply', 'beginner', 'module', 'm01-what-a-terminal-measures', 4, 'A form sends volumeAtDip a tank with its strapping table and a dip box left blank. What does the engine answer?', '["0.000 m3, the volume at 0 mm on AK-01''s table", "REFUSED: No dip reading.", "REFUSED: A dip cannot be negative.", "REFUSED: No strapping table for this tank."]'::jsonb, 1, 'A blank dip and a null dip return the same refusal. A blank box never becomes 0 mm, because 0 mm is the empty tank and reads 0.000 m3, which is a different fact.'),
  ('supply', 'beginner', 'module', 'm01-what-a-terminal-measures', 5, 'reconcileStock is given the opening stock, the receipts, the deliveries and the known losses of the AKODO day, and no closing dip. What comes back?', '["REFUSED: No opening stock, so the day cannot be closed. The opening stock is yesterday''s closing dip.", "expected closing 4508.100 m3 and unaccounted 0.000 m3, the day read as balanced", "expected closing 4508.100 m3 and unaccounted none, with a note that the day cannot be closed", "a refusal with no figure at all, because the ledger needs both ends before any line of it is formed"]'::jsonb, 2, 'The expected closing needs only the opening stock and the day''s movements, so 4508.100 m3 prints. The unaccounted figure needs the dip, so it reads none.'),
  ('supply', 'beginner', 'module', 'm01-what-a-terminal-measures', 6, 'Which of these calls returns a partial answer with a named gap when one input is missing, and does not refuse?', '["volumeAtDip with no table", "volumeCorrectionFactor with no density", "reconcileStock with no opening stock", "dipToStandardVolume with no VCF"]'::jsonb, 3, 'dipToStandardVolume still has everything it needs for the gross, so it reports gross 3461.489 m3 and gives the standard volume as none. The other three have nothing to form and refuse.'),
  ('supply', 'beginner', 'module', 'm01-what-a-terminal-measures', 7, 'Which of these is one of terminalDepot''s 8 exported functions?', '["buildPumpPrice", "trendUnaccounted", "cargoQuantities", "fleetSizing"]'::jsonb, 1, 'terminalDepot exports dipToStandardVolume, rackQueue, reconcileStock, tankFarmCover, throughputEconomics, trendUnaccounted, volumeAtDip and volumeCorrectionFactor. buildPumpPrice, cargoQuantities and fleetSizing are three of fuelPricing''s 9.'),
  ('supply', 'beginner', 'module', 'm01-what-a-terminal-measures', 8, 'What does IMPORT_TEMPLATE tell a user about each of its line items, from ocean freight to the demurrage provision?', '["Which charge exists, its basis and its stage, with the rate left for the user to supply.", "A typical rate for each charge, labelled as a starting point in the same way as PRODUCT_REFERENCE.", "The rate in force when the engine was built, with a note to confirm it against the regulation.", "The order of the charges, with a rate of zero wherever the user leaves one blank."]'::jsonb, 0, 'The rate shipped column reads none on all 9 rows. RATE_DISCLAIMER says every rate is a required input, so the template names charges and bases and never an amount.'),
  ('supply', 'beginner', 'module', 'm01-what-a-terminal-measures', 9, 'PRODUCT_REFERENCE lists PMS at a typical density of 745 kg/m3. When does anything in fuelPricing read that figure?', '["Whenever a PMS tank''s density is left blank, as the default for its volume correction factor.", "Whenever a measured density falls outside 720-775 kg/m3.", "On every PMS call, in place of the sample density.", "Only when a caller passes it in; the certificate of quality is the authority."]'::jsonb, 3, 'The engine labels these densities a starting point: nothing in the module reads them unless a caller passes one in, and the certificate of quality is the authority. PMS reads 745 kg/m3 only as a label.'),
  ('supply', 'beginner', 'module', 'm01-what-a-terminal-measures', 10, 'volumeCorrectionFactor refuses a call made with no coefficients. Which two ways forward does its refusal offer?', '["Supply K0, K1 and K2, or accept the product''s typical density.", "Enter a VCF of 1.000000, or state the density at 15 C and let the engine pick a row.", "Supply K0, K1 and K2, or enter a VCF read from your own tables.", "Pick a commodity group from the engine''s own table."]'::jsonb, 2, 'The refusal names the API MPMS Chapter 11.1 coefficients, says the package does not ship them, and offers exactly two routes: supply K0, K1 and K2, or enter a VCF from your own tables.'),
  ('supply', 'beginner', 'module', 'm01-what-a-terminal-measures', 11, 'volumeCorrectionFactor is called with coefficients and an observed temperature, and the density box is empty. What does the engine answer?', '["REFUSED: Density is required to convert between mass and volume; it is not assumed.", "REFUSED: Density at 15 C and observed temperature are both needed.", "a VCF worked at the typical density of 745 kg/m3", "REFUSED: No volume correction factor supplied, so only the gross observed volume is reported."]'::jsonb, 1, 'The form needs its two measured inputs. The mass and volume sentence belongs to cargoQuantities, and the note about a missing VCF is dipToStandardVolume''s, which does not refuse.'),
  ('supply', 'beginner', 'module', 'm01-what-a-terminal-measures', 12, 'In the Associate chain, free water has just been read through the table and taken off. What is the next link?', '["A volume correction factor turns the gross observed volume into a volume at standard.", "The day closes on the gross observed volume, and the correction is applied to the gap afterwards.", "The table is read again at the gross volume to find its height.", "The days are summed and read for a direction."]'::jsonb, 0, 'The six links run dip, table, free water, VCF, the day and the run of days. The gross observed volume, such as AK-01''s 3461.489 m3, is corrected to standard before the day is closed.'),
  ('supply', 'beginner', 'module', 'm01-what-a-terminal-measures', 13, 'The course runs on three invented records. Which one is the coastal import terminal with three tanks whose readings this tier uses?', '["IBAFO, the depot with the loading rack", "BADAGRY, the petrol cargo priced to the nozzle", "A real terminal, since a stock needs real dips", "AKODO"]'::jsonb, 3, 'AKODO is the coastal import terminal with three tanks, AK-01 to AK-03. IBAFO is the inland depot and BADAGRY the cargo, and all three records are invented for the course.'),
  ('supply', 'beginner', 'module', 'm01-what-a-terminal-measures', 14, 'throughputEconomics is called with every input except an emission factor. How does the engine answer?', '["It refuses the whole call, since the carbon side is incomplete.", "It computes the emissions with a typical factor labelled as a starting point, as it does with densities.", "It reports the margin, gives the emissions as none and says why in a note.", "It reports emissions of 0.000, as a missing factor adds nothing."]'::jsonb, 2, 'The note says factors are published, versioned data and an invented one would be worse than none. A missing value stays missing and is never read as 0.'),
  ('supply', 'beginner', 'module', 'm01-what-a-terminal-measures', 15, 'When one measured input is left blank, null or absent, which three kinds of answer does the engine give?', '["It refuses, or takes a typical figure and labels it a starting point.", "It refuses, reports the figure it cannot form as none, or labels its answer incomplete.", "It reads the blank as zero, or refuses when zero would make no sense at all.", "It fills a default from its constants, warns in a note, or refuses the call."]'::jsonb, 1, 'The table of missing inputs answers every call one of those three ways: a refusal in the engine''s own sentence, a figure given as none beside the ones it could form, or an answer labelled incomplete. No row fills a blank with a typical figure, a default or a zero.'),
  ('supply', 'beginner', 'module', 'm02-the-strapping-table', 1, 'AK-01 is dipped at 9318 mm. Between which two entries of its 250 mm table does volumeAtDip draw its line?', '["9500 mm at 3611.261 m3 and 14750 mm at 5606.957 m3", "9250 mm at 3516.228 m3 and 9500 mm at 3611.261 m3", "0 mm at 0.000 m3 and 9500 mm at 3611.261 m3", "250 mm at 95.033 m3 and 9500 mm at 3611.261 m3"]'::jsonb, 1, 'The entry just below and the entry just above bracket the dip, and the straight line joining them reads 3542.077 m3 at 9318 mm.'),
  ('supply', 'beginner', 'module', 'm02-the-strapping-table', 2, 'What does volumeAtDip do with a dip that falls between two entries of a strapping table?', '["It returns the volume of the nearer entry, so a dip reads the tabled height closest to it.", "It rebuilds the tank''s shape from its diameter and computes the volume at the dip.", "It returns the volume of the entry below, so a stock never counts product the table has not listed.", "It draws a straight line between the entry below and the entry above, and reads the volume off that line at the dip."]'::jsonb, 3, 'Linear interpolation is the whole of what volumeAtDip does between entries: two entries and one dip are the whole input, as when 9318 mm reads 3542.077 m3 on AK-01.'),
  ('supply', 'beginner', 'module', 'm02-the-strapping-table', 3, 'AK-01''s 250 mm table and the same tank strapped every 10 mm both read 3542.077 m3 at the 9318 mm dip. Why do they agree to the litre?', '["AK-01 is a vertical cylinder, which is linear in height, so the straight line between two entries is exact.", "The engine refines a coarse table to a 10 mm step before it interpolates.", "The dip of 9318 mm lands on an entry of both tables, so neither interpolates.", "Both volumes are rounded to the litre, which hides what a coarse step costs."]'::jsonb, 0, 'Every millimetre of a vertical cylinder adds the same slice, so a coarser step costs nothing at the dip: 3542.077 m3 and 3542.077 m3.'),
  ('supply', 'beginner', 'module', 'm02-the-strapping-table', 4, 'At 41 mm on AK-03 the 100 mm table reads 0.341 m3 and the 10 mm table 0.220 m3. Which figure does the digest print for the 100 mm table less the 10 mm table?', '["-0.007 m3, the difference at that tank''s morning dip", "0.341 m3, since the finer table reads no water", "0.120 m3", "0.220 m3, the reading on the finer of the two tables"]'::jsonb, 2, 'The last column is computed from the unrounded volumes, so the printed 0.120 m3 is the figure to quote. It is never recomputed from the rounded columns.'),
  ('supply', 'beginner', 'module', 'm02-the-strapping-table', 5, 'At AK-03''s morning dip of 1847 mm, which of its two tables reads the higher volume?', '["The 100 mm table, 52.501 m3 against 52.508 m3", "The 10 mm table, 52.508 m3 against 52.501 m3", "Neither, since the two agree to the litre as AK-01''s tables do at 9318 mm", "The 100 mm table, by the 0.120 m3 printed for that bullet"]'::jsonb, 1, 'The 100 mm table less the 10 mm table is -0.007 m3 at 1847 mm, so the finer table reads the higher volume there. The 0.120 m3 belongs to the 41 mm height.'),
  ('supply', 'beginner', 'module', 'm02-the-strapping-table', 6, 'AK-01 is dipped at 14800 mm, above its last entry of 14750 mm. What does the engine answer?', '["REFUSED: The dip is below the first strapping entry. The table does not cover this height; extend it down to the tank floor.", "5606.957 m3, the dip held at the last entry with a warning beside it", "REFUSED: No dip reading.", "REFUSED: The dip is above the last strapping entry. The table does not cover this height, and extrapolating one invents capacity the tank does not have."]'::jsonb, 3, 'At 14750 mm the dip lands on the last entry and reads 5606.957 m3. Above it there is one point and nothing to interpolate to, so the engine refuses.'),
  ('supply', 'beginner', 'module', 'm02-the-strapping-table', 7, 'Why will volumeAtDip not carry the slope of the last step upward to read a dip above the last entry?', '["Above the last entry the engine needs the tank''s diameter, which a strapping table does not carry.", "A dip above the last entry is always a typing error, so the engine treats it as no reading at all.", "A line carried past the last entry would invent capacity the tank does not have.", "The engine keeps extrapolation for horizontal tanks, whose curve it can follow past the last entry."]'::jsonb, 2, 'The refusal gives the reason in its own words: the table does not cover this height, and extrapolating one invents capacity the tank does not have. AK-02 at 12010 mm and AK-03 at 3010 mm, the bullet, are refused with the same sentence.'),
  ('supply', 'beginner', 'module', 'm02-the-strapping-table', 8, 'A partial calibration of AK-01 starts at 300 mm with 114.040 m3. A dip of 180 mm is put to it. What does the engine answer?', '["REFUSED: The dip is below the first strapping entry. The table does not cover this height; extend it down to the tank floor.", "gross 114.040 m3, the dip read at the first entry", "REFUSED: A dip cannot be negative.", "REFUSED: The dip is above the last strapping entry. The table does not cover this height, and extrapolating one invents capacity the tank does not have."]'::jsonb, 0, 'The table states nothing below 300 mm, so there is no second point to draw a line to. The refusal sends the user back to the calibration.'),
  ('supply', 'beginner', 'module', 'm02-the-strapping-table', 9, 'On that partial table, why does the engine not draw a line from an empty tank at 0 mm up to the first entry?', '["It does draw that line whenever the first entry sits below 800 mm, which is where this table ends.", "The table does not cover that height, and the refusal asks for it to be extended down to the tank floor.", "It reads any dip below the first entry as a negative dip, and refuses it with that sentence.", "The line would need the product''s density, and a strapping table holds heights and volumes only."]'::jsonb, 1, 'The partial table starts at 300 mm, where the volume is 114.040 m3 and not the empty tank. A dip of 180 mm gets the refusal for a dip below the first strapping entry, which ends by asking for the table to be extended down to the tank floor. A negative dip gets a different sentence.'),
  ('supply', 'beginner', 'module', 'm02-the-strapping-table', 10, 'Two dips are refused: 180 mm on the partial table and -5 mm on AK-01''s full table. What cures each?', '["A fresh reading for the 180 mm dip, and more calibration for the -5 mm dip.", "A fresh reading for both, since each dip lies below the table and must be taken again.", "More calibration for both, extending each table down past the height that was refused.", "More calibration for the 180 mm dip, and a fresh reading for the -5 mm dip."]'::jsonb, 3, '180 mm is a real height the calibration does not cover. -5 mm is a height that cannot exist. Both stop the chain at its first link.'),
  ('supply', 'beginner', 'module', 'm02-the-strapping-table', 11, 'AK-01''s partial calibration runs from 300 mm to 800 mm. Put to it through dipToStandardVolume with no water, what does a dip of 640 mm return?', '["gross 114.040 m3", "Refused", "gross 243.285 m3", "gross 3542.077 m3"]'::jsonb, 2, '640 mm lies inside the partial table and reads gross 243.285 m3 with no water. 300 mm, its first entry, reads 114.040 m3, and a dip of 180 mm below it is refused. 3542.077 m3 is AK-01''s morning dip of 9318 mm on the full table.'),
  ('supply', 'beginner', 'module', 'm02-the-strapping-table', 12, 'AK-03''s strapping table has 31 entries every 100 mm. Which are its first and its last entries?', '["From 0.000 m3 at 0 mm to 81.289 m3 at 3000 mm", "From 0.000 m3 at 0 mm to 2412.743 m3 at 12000 mm", "From 50.925 m3 at 1800 mm to 54.279 m3 at 1900 mm", "From 0.000 m3 at 0 mm to 52.501 m3 at 1847 mm"]'::jsonb, 0, 'AK-03, the horizontal bullet 3 m across and 11.5 m long, is strapped from 0 mm = 0.000 m3 to 3000 mm = 81.289 m3. 12000 mm is AK-02''s last entry; 1800 mm and 1900 mm are the entries that bracket AK-03''s morning dip of 1847 mm, which is no entry.'),
  ('supply', 'beginner', 'module', 'm02-the-strapping-table', 13, 'Which step and which count of entries belong to AK-02''s strapping table?', '["250 mm, 60 entries", "250 mm, 49 entries", "100 mm, 31 entries", "10 mm, 301 entries"]'::jsonb, 1, 'AK-02, the vertical AGO tank 16 m across, is strapped every 250 mm to 12000 mm in 49 entries. 60 entries is AK-01''s table, 31 entries AK-03''s, and 301 entries the bullet strapped every 10 mm.'),
  ('supply', 'beginner', 'module', 'm02-the-strapping-table', 14, 'Swept up AK-01''s own table, which of these heights does the engine interpolate?', '["250 mm", "9500 mm", "0 mm", "125 mm"]'::jsonb, 3, '0 mm, 250 mm and 9500 mm are entries of the 250 mm table and return their own volumes. 125 mm sits between entries and reads 47.517 m3 by interpolation.'),
  ('supply', 'beginner', 'module', 'm02-the-strapping-table', 15, 'Which volume does volumeAtDip return for AK-01 dipped exactly on the highest height its table lists?', '["3611.261 m3", "A refusal above the last entry", "5606.957 m3", "2412.743 m3"]'::jsonb, 2, 'A dip on the last entry reads that entry''s own volume, 5606.957 m3. Only a dip above it, such as 14800 mm, is refused. 3611.261 m3 is the 9500 mm entry, and 2412.743 m3 is AK-02''s last entry.'),
  ('supply', 'beginner', 'module', 'm03-free-water-and-the-gross-volume', 1, 'dipToStandardVolume is given a dip and a water cut. Through what does it turn the water cut into a volume?', '["A separate water table the terminal keeps for its tank bottoms.", "A fixed volume per millimetre of water, the same for every tank.", "The same strapping table that reads the dip.", "The table read once at the dip less the water height."]'::jsonb, 2, 'The water lies at the bottom of the same tank, so the same calibration turns its height into a volume. On AK-02 the 95 mm cut reads 19.101 m3 through that table.'),
  ('supply', 'beginner', 'module', 'm03-free-water-and-the-gross-volume', 2, 'AK-02 stays dipped at 5406 mm while its water cut is raised from 95 mm to 400 mm. Which figures move?', '["Water goes from 19.101 m3 to 80.425 m3 and gross from 1067.840 m3 to 1006.516 m3, while the volume at the dip stays 1086.941 m3.", "The volume at the dip goes from 1086.941 m3 to 1006.516 m3, while the water volume stays 19.101 m3.", "Only the gross moves, from 1067.840 m3 to 1006.516 m3, since the water volume is fixed by the tank.", "Nothing moves, since 400 mm of water is still below the dip of 5406 mm."]'::jsonb, 0, 'The dip has not changed, so neither has the volume at the dip, 1086.941 m3. The water volume rises to 80.425 m3 and the gross falls to 1006.516 m3.'),
  ('supply', 'beginner', 'module', 'm03-free-water-and-the-gross-volume', 3, 'AK-02''s water cut is set equal to its dip, 5406 mm. What does the engine answer?', '["REFUSED: The water cut is above the product dip. Check both readings.", "water 0.000 m3, gross 1086.941 m3, the cut read as no water at all", "water 1086.941 m3 and gross none, since a tank of water holds no product", "water 1086.941 m3, gross 0.000 m3"]'::jsonb, 3, 'A water cut equal to the dip is possible: the tank holds water and no product, so the whole 1086.941 m3 is water and the gross is 0.000 m3.'),
  ('supply', 'beginner', 'module', 'm03-free-water-and-the-gross-volume', 4, 'A water cut of 5500 mm is typed against AK-02''s dip of 5406 mm. Which answer comes back?', '["water 1086.941 m3, gross 0.000 m3, the water trimmed down to the dip", "REFUSED: The water cut is above the product dip. Check both readings.", "REFUSED: A water cut cannot be negative.", "water 1105.841 m3, read at the 5500 mm entry, and gross none"]'::jsonb, 1, 'A water cut above the product dip is refused, and the sentence asks for both readings to be checked. A cut equal to the dip, 5406 mm, is not refused: it reads water 1086.941 m3 and gross 0.000 m3.'),
  ('supply', 'beginner', 'module', 'm03-free-water-and-the-gross-volume', 5, 'A gauger types -3 mm for the water on the diesel tank. How does the engine answer?', '["Clamped to 0 mm: water 0.000 m3, gross 1086.941 m3", "Refused as a negative dip", "Refused as a negative water cut", "Refused as no dip reading"]'::jsonb, 2, 'The engine refuses with its own sentence for the water: A water cut cannot be negative. It never clamps the cut to 0 mm, which is a real reading that returns water 0.000 m3 and gross 1086.941 m3. The negative-dip sentence belongs to the dip.'),
  ('supply', 'beginner', 'module', 'm03-free-water-and-the-gross-volume', 6, 'With AK-01''s partial calibration in use, the product reads 640 mm and the water cut 150 mm. Which answer comes back from dipToStandardVolume?', '["REFUSED: The water cut cannot be converted: The dip is below the first strapping entry. The table does not cover this height; extend it down to the tank floor.", "REFUSED: The water cut is above the product dip. Check both readings.", "REFUSED: A water cut cannot be negative.", "gross 243.285 m3, the water left out because the table cannot read it"]'::jsonb, 0, 'The dip of 640 mm is inside the table, but 150 mm lies below its first entry, so the water volume cannot be read and there is no gross. The refusal carries the table''s own sentence.'),
  ('supply', 'beginner', 'module', 'm03-free-water-and-the-gross-volume', 7, 'Which water volume comes off AK-03''s volume at the dip for its 41 mm cut?', '["0.220 m3", "0.120 m3", "51.126 m3", "0.341 m3"]'::jsonb, 3, 'The 41 mm cut goes through AK-03''s own 100 mm table and reads 0.341 m3, which leaves gross 52.161 m3. 0.220 m3 is the same height on the 10 mm table, 0.120 m3 the difference between the two tables there, and 51.126 m3 the shortcut read at 1806 mm.'),
  ('supply', 'beginner', 'module', 'm03-free-water-and-the-gross-volume', 8, 'The 150 mm water cut on AK-01''s partial calibration is refused because it lies below the table''s first entry. Which is that first entry?', '["0 mm at 0.000 m3, the empty tank", "300 mm at 114.040 m3", "250 mm at 95.033 m3", "125 mm at 47.517 m3"]'::jsonb, 1, 'The partial table starts at 300 mm, where the volume is 114.040 m3 and not the empty tank, and ends at 800 mm. 0 mm, 125 mm and 250 mm are heights on AK-01''s full table.'),
  ('supply', 'beginner', 'module', 'm03-free-water-and-the-gross-volume', 9, 'On AK-03, dipped at 1847 mm with 41 mm of water, a shortcut subtracts the heights first and reads the table once at 1806 mm. What does it give against the engine''s gross?', '["52.161 m3 against the gross 51.126 m3", "52.501 m3 against the gross 52.161 m3", "51.126 m3 against the gross 52.161 m3", "51.126 m3 against the gross 52.508 m3"]'::jsonb, 2, 'The engine reads each height through the table where it was measured. The shortcut reads 51.126 m3 because the water fills the narrow bottom of a curved tank.'),
  ('supply', 'beginner', 'module', 'm03-free-water-and-the-gross-volume', 10, 'On AK-01, the shortcut reads 3461.488 m3 at 9106 mm against the engine''s gross of 3461.489 m3. What about AK-01 puts the two readings there?', '["It is a vertical cylinder, holding the same volume in every millimetre of height.", "Its 250 mm step is fine enough that no reading between entries departs from the tank.", "Its water cut of 212 mm is small enough for the shortcut to be the engine''s own method.", "The engine switches to the shortcut on vertical tanks and keeps it off the bullet."]'::jsonb, 0, 'On a vertical tank a slice of height holds the same volume wherever it is taken, so the two readings land at 3461.488 m3 and 3461.489 m3. The engine never takes the shortcut on any tank.'),
  ('supply', 'beginner', 'module', 'm03-free-water-and-the-gross-volume', 11, 'Which of AK-01''s morning figures is the petrol stock at observed temperature?', '["3542.077 m3", "3461.488 m3", "80.588 m3", "3461.489 m3"]'::jsonb, 3, '3542.077 m3 is the volume at the dip, which still includes the water. 80.588 m3 is the water. 3461.488 m3 is the shortcut reading the engine never uses.'),
  ('supply', 'beginner', 'module', 'm03-free-water-and-the-gross-volume', 12, 'AK-03''s row prints volume at the dip 52.501 m3, water 0.341 m3 and gross observed 52.161 m3. Which gross should a report quote?', '["The printed dip volume less the printed water, worked out from the rounded columns of the row", "52.161 m3, the printed gross, which the engine forms from the unrounded volumes", "51.126 m3, the table read once at the dip less the water height", "52.501 m3, since 41 mm of water sits below the bullet''s first step"]'::jsonb, 1, 'The engine computes each gross from the unrounded volumes, so a printed pair can differ from the printed gross in the third decimal. Quote the printed 52.161 m3.'),
  ('supply', 'beginner', 'module', 'm03-free-water-and-the-gross-volume', 13, 'The three AKODO tanks total 4581.490 m3 gross observed. What does the word gross say about that total?', '["Free water has come off and nothing else has: the volume still stands at its observed temperature.", "The total is at standard, the stock the AKODO day is closed on.", "The water is still in it, and gross marks it as the total at the dip.", "The heel below each outlet has come off, leaving only pumpable product."]'::jsonb, 0, 'Gross means free water off. Observed means at this morning''s temperatures, so 4581.490 m3 mixes three temperatures and three products and is not yet a stock to close a day on.'),
  ('supply', 'beginner', 'module', 'm03-free-water-and-the-gross-volume', 14, 'AK-02''s water cut, dipped at 5406 mm, is typed as 0 mm. How is that treated?', '["Refuses it, since 0 mm of water is read the same way as a blank box with no reading in it.", "Assumes the tank''s usual water of 95 mm, since a tank that is truly dry is unlikely.", "Takes it as a real reading and removes nothing, so the gross is 1086.941 m3.", "Reports the gross as none until a water cut above 0 mm is given."]'::jsonb, 2, 'A stated cut of 0 mm is a real reading, and it removes nothing. The swept table reads water 0.000 m3, gross 1086.941 m3 for it.'),
  ('supply', 'beginner', 'module', 'm03-free-water-and-the-gross-volume', 15, 'On the partial table with the dip at 640 mm, which water cut is refused with the sentence about water above the product dip?', '["150 mm", "700 mm", "-10 mm", "0 mm"]'::jsonb, 1, '700 mm stands above the 640 mm dip. 150 mm is refused because the table cannot convert it, -10 mm because a cut cannot be negative, and 0 mm returns gross 243.285 m3.'),
  ('supply', 'beginner', 'module', 'm04-the-volume-correction-factor', 1, 'On the course''s synthetic coefficient row at 741.6 kg/m3, the VCF at 15 C reads 1.000000. What does that do to a gross observed volume?', '["It shrinks it by the second order term in the bracket with 0.8, which is present even at 15 C.", "Nothing: at 15 C the standard volume equals the gross observed volume.", "It raises it slightly, since 15 C sits below every AKODO tank''s temperature.", "It marks the volume as uncorrected, since a VCF of exactly one means no factor was supplied at all."]'::jsonb, 1, 'In VCF = exp( -alpha x dT x (1 + 0.8 x alpha x dT) ), dT is zero at 15 C, so the exponent is zero and the factor is exactly 1.000000.'),
  ('supply', 'beginner', 'module', 'm04-the-volume-correction-factor', 2, 'The synthetic form at 741.6 kg/m3 is warmed from 20 C to 40 C. Which figures move?', '["alpha falls from 0.001350036 to 0.000975309 and the VCF falls with it from 0.993236 to 0.965932.", "The VCF rises from 0.993236 to 1.006736 while alpha stays 0.001350036.", "Both stay put, since the synthetic row fixes the VCF for a density.", "The VCF falls from 0.993236 to 0.965932 while alpha stays 0.001350036."]'::jsonb, 3, 'alpha is built from density and the coefficients alone, so it reads 0.001350036 in every row of the temperature sweep. Temperature enters only the second line of the form.'),
  ('supply', 'beginner', 'module', 'm04-the-volume-correction-factor', 3, 'The synthetic form at 31.5 C is swept from 700 kg/m3 to 900 kg/m3. Which way do alpha and the VCF move?', '["alpha falls from 0.001489796 to 0.000975309 and the VCF rises from 0.975246 to 0.983832.", "alpha rises from 0.000975309 to 0.001489796 and the VCF falls from 0.983832 to 0.975246 as the product gets denser.", "alpha stays 0.001350036 and only the VCF moves, from 0.975246 to 0.983832.", "Both fall together, alpha to 0.000975309 and the VCF to 0.975246."]'::jsonb, 0, 'Density sits under K0 and K1 in alpha = K0 / rho^2 + K1 / rho + K2. On this row alpha falls from 0.001489796 at 700 kg/m3 to 0.000975309 at 900 kg/m3, and the VCF rises from 0.975246 to 0.983832.'),
  ('supply', 'beginner', 'module', 'm04-the-volume-correction-factor', 4, 'In the temperature sweep of the synthetic row, alpha reads 0.001350036 at every temperature. Why?', '["The engine holds alpha fixed at its 15 C value and corrects it later.", "alpha is rounded to nine decimals, which hides the effect of temperature.", "alpha depends only on the density and the coefficients.", "A commodity group has one alpha at any density."]'::jsonb, 2, 'The first line of the form builds alpha from rho and K0, K1 and K2. The density sweep at 31.5 C shows alpha moving from 0.001489796 to 0.000975309 as the density changes.'),
  ('supply', 'beginner', 'module', 'm04-the-volume-correction-factor', 5, 'The correction form is written with rho. Which density is rho?', '["The density at the observed temperature", "The density at 15 C, in kg/m3", "The typical density in PRODUCT_REFERENCE", "The density of the free water"]'::jsonb, 1, 'The form states rho as the density at 15 C in kg/m3, and the refusal without one asks for the density at 15 C and the observed temperature. PRODUCT_REFERENCE is read only when a caller passes one of its densities in.'),
  ('supply', 'beginner', 'module', 'm04-the-volume-correction-factor', 6, 'What is dT in VCF = exp( -alpha x dT x (1 + 0.8 x alpha x dT) )?', '["15 C less the observed temperature", "The change in temperature since yesterday''s closing dip", "The density at 15 C less the density at the observed temperature", "The observed temperature less 15 C"]'::jsonb, 3, 'dT measures how far the product sits from the reference temperature. At 31.5 C it is positive and the synthetic VCF at 741.6 kg/m3 is 0.977583, below one.'),
  ('supply', 'beginner', 'module', 'm04-the-volume-correction-factor', 7, 'The course prints the coefficients K0 = 520, K1 = 0.3 and K2 = 0. What are they?', '["AKODO''s own coefficients, which correct the stock in its petrol tank.", "The engine''s default row, applied when a caller supplies no coefficients.", "Synthetic coefficients invented for the course to show the form; they correct no stock.", "The coefficients behind AK-01''s typed VCF of 0.980300 at 31.5 C."]'::jsonb, 2, 'They belong to no commodity group. The engine ships no coefficients and has no default, and AKODO corrects its stock with VCFs typed off its own tables.'),
  ('supply', 'beginner', 'module', 'm04-the-volume-correction-factor', 8, 'The correction form takes five inputs: rho, the observed temperature, and K0, K1 and K2. Which are the tank''s own figures and which come from a published table?', '["rho and the temperature are the tank''s own; K0, K1 and K2 are published per commodity group.", "rho and K0 are the tank''s own; the temperature, K1 and K2 are published per group.", "All five are the tank''s own, typed in beside its dip and its water cut.", "The temperature is the tank''s own; rho and the three K values come from PRODUCT_REFERENCE."]'::jsonb, 0, 'AKODO prints a density and a temperature for each tank. The coefficients are a published table per commodity group; the engine ships none, has no default and refuses without them. PRODUCT_REFERENCE carries typical densities only.'),
  ('supply', 'beginner', 'module', 'm04-the-volume-correction-factor', 9, 'volumeCorrectionFactor is called with a density and a temperature and no coefficients. Which coefficient row does the engine fall back on?', '["The synthetic row, K0 = 520, K1 = 0.3 and K2 = 0", "The nearest commodity group''s row", "A row with a VCF of 1.000000 at any temperature", "None: it has no default, and it refuses the call"]'::jsonb, 3, 'The engine ships no coefficients and has no default. It refuses, asking for K0, K1 and K2 or a VCF read from your own tables. The synthetic row is printed only to show the form, and no stock is corrected with it.'),
  ('supply', 'beginner', 'module', 'm04-the-volume-correction-factor', 10, 'AK-01''s gross observed volume could be multiplied by the synthetic form''s VCF at its density and temperature, or by the VCF typed off AKODO''s own tables. Which one touches the stock?', '["The synthetic VCF, since a computed form outranks a figure typed by hand", "The typed VCF, 0.980300", "Neither, until the synthetic and the typed figures agree", "The synthetic VCF, since it is worked at the same 741.6 kg/m3 and 31.5 C"]'::jsonb, 1, 'The synthetic figure is the form on invented coefficients, printed as an illustration. Only the typed figure, itself invented for the course, multiplies a stock: 3461.489 m3 becomes 3393.298 m3.'),
  ('supply', 'beginner', 'module', 'm04-the-volume-correction-factor', 11, 'AK-02 holds diesel at 846.3 kg/m3 and 30 C, and its VCF typed is 0.987600. Which of those figures came from a lookup?', '["The VCF, read off AKODO''s own tables for that density and temperature and typed in", "The density, read off PRODUCT_REFERENCE for diesel and typed in", "The temperature, read off the tank''s table at the dip of 5406 mm", "All three, since each is read off the synthetic sweep"]'::jsonb, 0, 'AKODO reads its VCF off its own tables for each tank''s density and temperature and types it in; 0.987600 is that lookup, invented for the course. AK-02''s 846.3 kg/m3 is not PRODUCT_REFERENCE''s 840 for AGO, and a strapping table holds heights and volumes only.'),
  ('supply', 'beginner', 'module', 'm04-the-volume-correction-factor', 12, 'The three printed standard volumes, each rounded to the litre, add to 4499.453 m3. On which total is the AKODO day closed?', '["4499.453 m3, the sum of the three printed standard volumes", "4581.490 m3, the total gross observed volume of the three tanks", "4499.452 m3, the total summed from the unrounded standard volumes", "4499.453 m3, since a stock is always quoted to the litre it prints"]'::jsonb, 2, 'The engine sums the unrounded standard volumes and the digest prints that total as 4499.452 m3. The sum of the printed rows is not the figure the day closes on.'),
  ('supply', 'beginner', 'module', 'm04-the-volume-correction-factor', 13, 'The morning has two totals, 4581.490 m3 and 4499.452 m3. Which can be set against an opening stock held at standard?', '["4581.490 m3, since it counts every litre in the tanks with the water off", "Either, since both are in m3 and both have the free water removed", "4581.490 m3, since it is the larger and so the more complete of the two", "4499.452 m3"]'::jsonb, 3, '4581.490 m3 is the gross observed total, each tank at its own temperature of 31.5 C, 30 C and 29 C. 4499.452 m3 is the standard total the day is closed on. The same day closed on the gross against an opening held at standard reads unaccounted 73.390 m3, a gain outside tolerance.'),
  ('supply', 'beginner', 'module', 'm04-the-volume-correction-factor', 14, 'Which AKODO tank is corrected at a density of 846.3 kg/m3 and a temperature of 30 C?', '["AK-01", "AK-02", "AK-03", "None of them; that pair is a synthetic sweep point"]'::jsonb, 1, 'AK-02, the AGO tank, is corrected at 846.3 kg/m3 and 30 C with a typed VCF of 0.987600. AK-01 stands at 741.6 kg/m3 and 31.5 C, and AK-03 at 796.8 kg/m3 and 29 C. The synthetic density sweep prints 846.3 kg/m3 at 31.5 C, and no stock is corrected with it.'),
  ('supply', 'beginner', 'module', 'm04-the-volume-correction-factor', 15, 'AK-03 reads 52.161 m3 gross observed and 51.556 m3 at standard. Which figure turns the first into the second?', '["Its typed VCF, 0.988400", "The synthetic VCF, 0.980162", "Its water, 0.341 m3", "Known losses, 3.100 m3"]'::jsonb, 0, 'Standard volume = gross observed volume x VCF, and AKODO types each tank''s VCF off its own tables: 0.988400 for AK-03 at 796.8 kg/m3 and 29 C. The synthetic 0.980162 is worked at 31.5 C and corrects no stock, and the water is already off the gross.'),
  ('supply', 'beginner', 'module', 'm05-closing-the-day', 1, 'On the AKODO day, which figure comes from the ledger and which from the tanks?', '["The dipped closing, 4499.452 m3, is the ledger''s; the expected closing, 4508.100 m3, is the tanks''.", "Both come from the tanks, since the ledger only records the opening stock of 4953.700 m3.", "The expected closing, 4508.100 m3, is the ledger''s; the dipped closing, 4499.452 m3, is the tanks''.", "Both come from the ledger, which is then checked against the throughput of 6182.500 m3."]'::jsonb, 2, 'expected closing = opening + receipts - deliveries - known losses, which is paperwork. The dipped closing is the standard total the tank chain built from tapes and tables.'),
  ('supply', 'beginner', 'module', 'm05-closing-the-day', 2, 'The AKODO day reads unaccounted -8.648 m3. What does the negative sign say?', '["A loss: the tanks hold less than the ledger expected.", "A gain: the tanks hold more than the ledger expected.", "A loss outside tolerance, since any negative gap fails the day.", "Nothing yet, since the sign is set only after the run of days is read."]'::jsonb, 0, 'unaccounted = dipped closing - expected closing. The dip is below the ledger, so the engine reports direction loss, and within tolerance true against a band of 12.365 m3.'),
  ('supply', 'beginner', 'module', 'm05-closing-the-day', 3, 'The AKODO day goes to reconcileStock with everything in place except the figure that starts the ledger. What is the answer?', '["expected closing 4508.100 m3, unaccounted none; note: No closing dip, so the day cannot be closed.", "unaccounted computed from an opening of 0.000 m3, with a note beside it saying the opening stock was assumed to be empty", "unaccounted 0.000 m3, balanced, with the opening taken from today''s own closing dip", "REFUSED: No opening stock, so the day cannot be closed. The opening stock is yesterday''s closing dip."]'::jsonb, 3, 'Without the opening stock the call is refused. The refusal names where the figure comes from: yesterday''s closing dip.'),
  ('supply', 'beginner', 'module', 'm05-closing-the-day', 4, 'The demonstration takes the opening stock as closing dip - receipts + deliveries + known losses. With a closing dip of 4380.250 m3 it opens on 4825.850 m3. Why does the day read balanced?', '["The closing dip of 4380.250 m3 happens to fall inside the tolerance band of 12.365 m3 on that day.", "The ledger undoes exactly what the derivation did, so the expected closing is the dip itself whatever it reads.", "The engine detects that the opening was derived and switches off the check with the word balanced.", "The derived opening stock is at standard, while the real opening of 4953.700 m3 is gross observed."]'::jsonb, 1, 'With the opening taken that way, the expected closing is the dip itself, whatever the dip reads. Every row of the demonstration balances with unaccounted 0.000 m3, so none of them measured anything.'),
  ('supply', 'beginner', 'module', 'm05-closing-the-day', 5, 'Both the real AKODO day and the derived day close on 4499.452 m3. The real day opens on 4953.700 m3 and the derived day on 4945.052 m3. Which one measures the terminal?', '["The derived day, because its opening is built from today''s own figures and so is more current.", "The real day, because its opening stock was measured before today''s dips were taken.", "The derived day, because a balanced reading of 0.000 m3 is the goal of every reconciliation.", "Neither, until the two opening stocks agree to within the tolerance band of the day."]'::jsonb, 1, 'The real day opens on yesterday''s closing dip and reads unaccounted -8.648 m3, direction loss, within 12.365 m3. The derived day reads 0.000 m3, balanced, and every row of that demonstration balances, so none of them measured anything.'),
  ('supply', 'beginner', 'module', 'm05-closing-the-day', 6, 'The AKODO tolerance is 0.2 percent. Of which figure is it a percent?', '["The opening stock, 4953.700 m3", "The expected closing, 4508.100 m3", "The dipped closing at standard, 4499.452 m3", "Throughput, receipts plus deliveries: 6182.500 m3"]'::jsonb, 3, 'tolerance = a stated percent of throughput, and throughput = receipts + deliveries. 0.2 percent of 6182.500 m3 is printed as 12.365 m3.'),
  ('supply', 'beginner', 'module', 'm05-closing-the-day', 7, 'The tolerance percent is moved from 0.1 to 0.2 on the same AKODO day. What changes?', '["The band goes from 6.183 m3 to 12.365 m3 and the verdict from false to true.", "The unaccounted figure goes from -8.648 m3 to 0.000 m3 and the verdict from false to true.", "The throughput goes from 3.091 m3 to 6.183 m3 while the verdict stays false in both rows.", "The band goes from 6.183 m3 to 12.365 m3 while the verdict stays true in both rows."]'::jsonb, 0, 'The unaccounted figure stays -8.648 m3 on the same day. Only the band moves, so the verdict depends on the stated percent.'),
  ('supply', 'beginner', 'module', 'm05-closing-the-day', 8, 'A still day: opening 4953.700 m3, no receipts and no deliveries, dipped at 4954.200 m3. Why is it outside tolerance?', '["A gain of 0.500 m3 is outside the 0.2 percent band, which on a still day is set on the opening stock instead.", "The engine refuses a day with no movements and reports the verdict as false.", "No product moved, so there is no throughput and the band is 0.000 m3.", "Any gain is outside, since the band covers losses only."]'::jsonb, 2, 'With no receipts and no deliveries there is no throughput, and the band is a stated percent of throughput. The still day prints a band of 0.000 m3 and reads outside it with its 0.500 m3 gain.'),
  ('supply', 'beginner', 'module', 'm05-closing-the-day', 9, 'The AKODO day prints unaccounted percent of throughput -0.1399 and a tolerance of 0.2 percent of throughput. How do the two percents differ?', '["The 0.2 is the stated band; the -0.1399 is the day''s result on the same base.", "The 0.2 is the day''s result; the -0.1399 is the band the terminal stated.", "The two are on different bases: the 0.2 on the opening stock, the -0.1399 on throughput.", "The -0.1399 is the cumulative percent over the nine days recorded."]'::jsonb, 0, 'Both percents sit on the throughput of 6182.500 m3. Keep the units apart: one is a band chosen before the day, the other what the day produced.'),
  ('supply', 'beginner', 'module', 'm05-closing-the-day', 10, 'How does reconcileStock form the expected closing?', '["opening + receipts - deliveries + known losses", "receipts - deliveries - known losses", "opening + receipts - deliveries - known losses", "dipped closing - receipts + deliveries + known losses"]'::jsonb, 2, 'expected closing = opening + receipts - deliveries - known losses, which on the AKODO day is 4508.100 m3. dipped closing - receipts + deliveries + known losses is how the demonstration derives an opening stock from the day''s own dip, which balances every day.'),
  ('supply', 'beginner', 'module', 'm05-closing-the-day', 11, 'Over nine days, what does trendUnaccounted report for the cumulative gap and the run?', '["cumulative -27.200 m3 and a run of 9 days, since every day is counted", "cumulative -27.200 m3 and a run of 6 days of loss ending on day 9", "cumulative -7.200 m3, the latest day, and a run of 3 days of loss", "cumulative 0.100 m3 at day 4 and a run of 5 days of loss after it"]'::jsonb, 1, 'The running total ends at -27.200 m3. From day 4, -2.400 m3, to day 9, -7.200 m3, every day is a loss, so the run ending on the latest day is 6 days.'),
  ('supply', 'beginner', 'module', 'm05-closing-the-day', 12, 'The same nine-day record is trimmed to its first six days. What does the engine report?', '["A run of 6 days of loss and the prompt", "A run of 3 days of loss and the prompt", "A run of 0 days and a mean percent of none", "A run of 3 days of loss and no prompt"]'::jsonb, 3, 'The first six days alone: run 3 days of loss; prompt: none. Trimmed one day at a time, runs of 2 and 3 days print no prompt and runs of 4, 5 and 6 days print one.'),
  ('supply', 'beginner', 'module', 'm05-closing-the-day', 13, 'The nine days'' cumulative percent is -0.0494. On what base is that percent taken?', '["The cumulative throughput, printed as 55085.000 m3", "The latest day''s throughput alone, 6310.000 m3 on day 9", "The AKODO day''s throughput, 6182.500 m3, on the one day closed", "The cumulative gap itself, -27.200 m3, over the nine days"]'::jsonb, 0, 'The engine prints the denominator of the mean percent as 55085.000 m3, the nine days'' throughput summed. The percent states the whole gap on the whole throughput.'),
  ('supply', 'beginner', 'module', 'm05-closing-the-day', 14, 'What three causes does the engine''s prompt name for a run in one direction?', '["A wet receipt, a leaking roof seal, or a strapping table cut too coarse", "A negative dip, a water cut above the dip, or a missing opening stock", "A tolerance set too tight, a still day, or a derived opening stock", "A drifting meter, a passing valve, or a temperature effect not being corrected"]'::jsonb, 3, 'The prompt reads: 6 days of loss in a row. One day is noise; a run in one direction is worth investigating: a drifting meter, a passing valve, or a temperature effect not being corrected.'),
  ('supply', 'beginner', 'module', 'm05-closing-the-day', 15, 'trendUnaccounted is given no days at all. What does it report?', '["REFUSED, since a trend needs at least one day to read", "cumulative 0.000 m3, run 0 and a mean percent of zero", "cumulative 0.000 m3, run 0 and mean percent none", "cumulative none, run none and mean percent none"]'::jsonb, 2, 'An empty record has nothing to average, so the mean percent is none. The running total of nothing is 0.000 m3 and there is no run.'),
  ('supply', 'beginner', 'module', 'm06-the-associate-reading', 1, 'Reading AK-01 end to end, what input stands behind its water figure of 80.588 m3?', '["The typed VCF of 0.980300, applied to the water", "AK-01''s own table, read at the 212 mm tape reading", "The dip of 9318 mm less the gross of 3461.489 m3", "A fixed share of the volume at the dip of 3542.077 m3"]'::jsonb, 1, 'The water cut is a second tape reading, 212 mm, turned into 80.588 m3 through the same strapping table that reads the 9318 mm dip.'),
  ('supply', 'beginner', 'module', 'm06-the-associate-reading', 2, 'The same AKODO day is closed on the gross closing stock of 4581.490 m3 against an opening stock held at standard. What does the engine read?', '["unaccounted -8.648 m3, direction loss, within tolerance true", "unaccounted 0.000 m3, balanced, within tolerance true", "REFUSED, since a gross closing stock cannot be put to reconcileStock", "unaccounted 73.390 m3, direction gain, within tolerance false"]'::jsonb, 3, 'The closing stock is gross observed at three observed temperatures and the opening is held at standard. On that basis the day reads unaccounted 73.390 m3, direction gain, within tolerance false.'),
  ('supply', 'beginner', 'module', 'm06-the-associate-reading', 3, 'Between the standard closing and the gross closing of the AKODO day, what is the one input that differs?', '["The closing stock: 4499.452 m3 at standard against 4581.490 m3 gross observed.", "The opening stock: 4953.700 m3 on one closing and 4945.052 m3 on the other.", "The tolerance: 0.2 percent on one closing and 0.1 percent on the other.", "The receipts: 2870.000 m3 on one closing and none on the other."]'::jsonb, 0, 'Only the closing stock moves. The standard closing matches the opening stock''s basis and reads a loss within tolerance; the gross closing reads a gain produced by mixing units.'),
  ('supply', 'beginner', 'module', 'm06-the-associate-reading', 4, 'Reading AK-03 backwards from its standard volume of 51.556 m3, how should its gross of 52.161 m3 be treated?', '["Rebuilt from the rounded 52.501 m3 and 0.341 m3 before it is multiplied by the VCF of 0.988400.", "Replaced by the shortcut reading of 51.126 m3, since the bullet''s curve makes the gross unreliable.", "Quoted as printed, since the engine forms it from the unrounded volumes at 1847 mm and 41 mm.", "Replaced by the 10 mm table''s reading of 52.508 m3."]'::jsonb, 2, '52.161 m3 is quoted as printed and is not rebuilt from the rounded columns. Multiplied by the typed 0.988400 it gives 51.556 m3 at standard.'),
  ('supply', 'beginner', 'module', 'm06-the-associate-reading', 5, 'At the end of the tank chain, a call returns gross 3461.489 m3 and standard none. Which link was left unsupplied?', '["The water cut", "The strapping table", "The VCF", "The opening stock"]'::jsonb, 2, 'A missing table or an unconvertible water cut refuses the whole call, and the opening stock belongs to the day. A missing VCF lets the gross print and names the standard volume none.'),
  ('supply', 'beginner', 'module', 'm06-the-associate-reading', 6, 'On AK-01''s partial table the dip reads 640 mm and the water 700 mm. How far down the chain does anything get formed?', '["The gross of 243.285 m3 is formed and only the standard volume is named none.", "The volume at the dip is formed and the water is left out with a note beside it.", "The chain runs to the day, which then reads the gap outside tolerance.", "Nothing is formed: the call is refused and no gross, standard volume or gap follows."]'::jsonb, 3, 'REFUSED: The water cut is above the product dip. Check both readings. A refused link stops the chain there, so nothing downstream is formed from it.'),
  ('supply', 'beginner', 'module', 'm06-the-associate-reading', 7, 'At a tolerance of 0.1 percent the AKODO band is 6.183 m3. What does the day then read?', '["The same -8.648 m3, now outside the band: within tolerance false.", "A smaller gap of 6.183 m3, since the band caps what can be reported.", "The same -8.648 m3, still within the band, since a loss is judged on one side.", "A refusal, since a band under the gap cannot close the day."]'::jsonb, 0, 'The unaccounted figure stays -8.648 m3. At 0.1 percent the band is 6.183 m3 and the day is outside it; at 0.2 percent it is 12.365 m3 and the day is within.'),
  ('supply', 'beginner', 'module', 'm06-the-associate-reading', 8, 'The nine-day record is kept to 7 days. What do the run and the prompt read?', '["A run of 4, with no prompt", "A run of 4, with the prompt", "A run of 7, with the prompt", "A run of 3, with no prompt"]'::jsonb, 1, 'Kept to 5 or 6 days the run is 2 or 3 days of loss and the prompt is none; kept to 7, 8 or 9 days the run is 4, 5 or 6 days and the prompt prints.'),
  ('supply', 'beginner', 'module', 'm06-the-associate-reading', 9, 'Two candidate openings exist for one day: yesterday''s dip at 4953.700 m3, or 4945.052 m3 worked back from today''s dip. What rule follows?', '["The opening stock may be taken from either source, provided the day closes inside its band.", "The opening stock is an input taken from before the day began, yesterday''s closing dip.", "The derived opening is to be preferred, since it is built from the day''s own measured figures.", "The two openings are averaged and the day closed on the mean."]'::jsonb, 1, 'The derived opening balances every day, 0.000 m3, so it measures nothing. The real opening reads -8.648 m3, a loss within 12.365 m3, because it could have come out wrong.'),
  ('supply', 'beginner', 'module', 'm06-the-associate-reading', 10, 'Which figure on the AKODO sheet is a tape height and no volume at all?', '["9318 mm", "3542.077 m3", "80.588 m3", "4499.452 m3"]'::jsonb, 0, '9318 mm is AK-01''s dip. 3542.077 m3 and 80.588 m3 are read through its table, and 4499.452 m3 is the standard total the day closes on.'),
  ('supply', 'beginner', 'module', 'm06-the-associate-reading', 11, 'What does the Professional tier add that the Associate tier never touched?', '["The coefficient table this tier refused, shipped at last for AKODO", "A second AKODO day, reconciled against the first", "Time spent waiting, money and carbon, at the inland depot IBAFO", "The BADAGRY cargo''s price at the pump"]'::jsonb, 2, 'The Professional tier moves to IBAFO and models its rack as a queue, its tank farm, its throughput economics and its lane. BADAGRY belongs to the Expert tier.'),
  ('supply', 'beginner', 'module', 'm06-the-associate-reading', 12, 'Which rule from this tier does the next tier carry over unchanged?', '["A VCF is always typed off the terminal''s own tables.", "A tolerance is always 0.2 percent of throughput.", "A strapping table is always read at 250 mm steps.", "A missing value stays missing."]'::jsonb, 3, 'The table of missing inputs covers both apps, and the next tier''s calls answer the same way: bays that are not a whole number, a missing distance or payload, and a missing demand are refused, never guessed.'),
  ('supply', 'beginner', 'module', 'm06-the-associate-reading', 13, 'Link two of the chain on AK-02: the dip of 5406 mm lies between 5250 mm at 1055.575 m3 and 5500 mm at 1105.841 m3. What is the input the engine cannot do without here?', '["AK-02''s typed VCF of 0.987600", "AK-02''s own strapping table", "AK-02''s density of 846.3 kg/m3", "AK-02''s water cut of 95 mm"]'::jsonb, 1, 'The table''s two entries and the dip are the whole input to volumeAtDip, which reads 1086.941 m3. With no table the engine refuses.'),
  ('supply', 'beginner', 'module', 'm06-the-associate-reading', 14, 'Across the whole AKODO reading, which reading of the table does the engine never take?', '["One reading at the dip, and another at the water cut", "One reading between two entries, drawn as a straight line", "One reading at an entry, when a dip lands exactly on it", "One reading at the dip less the water height"]'::jsonb, 3, 'On AK-03 the shortcut at the dip less the water reads 51.126 m3 against the gross 52.161 m3. The engine reads each height where it was measured.'),
  ('supply', 'beginner', 'module', 'm06-the-associate-reading', 15, 'Which list runs AK-01''s figures in the order the chain forms them: the dip, the volume at the dip, the gross observed volume, the standard volume?', '["9318 mm, 3542.077 m3, 3461.489 m3, 3393.298 m3", "9318 mm, 3461.489 m3, 3542.077 m3, 3393.298 m3", "9318 mm, 3542.077 m3, 3393.298 m3, 3461.489 m3", "9318 mm, 3542.077 m3, 3461.488 m3, 3393.298 m3"]'::jsonb, 0, 'The chain reads the table at the dip, takes the water off to reach the gross observed volume, and then applies the typed VCF for the standard volume. Swapping the gross and the volume at the dip, or the gross and the standard, breaks that order, and 3461.488 m3 is the shortcut reading the engine never takes.'),
  ('supply', 'beginner', 'final', null, 1, 'A tank with no calibration at all is put to volumeAtDip with a good dip. Which sentence comes back?', '["REFUSED: No dip reading.", "REFUSED: No strapping table for this tank.", "REFUSED: A dip cannot be negative.", "REFUSED: The dip is below the first strapping entry. The table does not cover this height; extend it down to the tank floor."]'::jsonb, 1, 'A strapping table is the only link between a height and a volume for one tank. With none, there is nothing to interpolate between, so any volume would be invented.'),
  ('supply', 'beginner', 'final', null, 2, 'AK-02''s strapping table ends at 12000 mm with 2412.743 m3. Over which heights can volumeAtDip read a dip on AK-02?', '["From 0 mm up to 12000 mm; a dip at 12010 mm is refused.", "From 0 mm upward, with heights past 12000 mm carried on the slope of the last step.", "Only at the entries themselves, one every 250 mm, since a dip must land on one.", "From 250 mm up to 12000 mm, since a dip of 0 mm counts as no reading."]'::jsonb, 0, 'AK-02''s table starts at the empty tank and stops at 12000 mm. Between the two it interpolates; the digest''s dip at 12010 mm gets the refusal for a dip above the last strapping entry.'),
  ('supply', 'beginner', 'final', null, 3, 'On the partial table with the dip held at 640 mm, the water cut is raised from 0 mm to 150 mm. What happens to the answer?', '["gross 243.285 m3 falls to 114.040 m3, the volume at the table''s first entry, as the water is taken off.", "gross 243.285 m3 is kept and the water is reported as none, since the dip is inside the table.", "gross 243.285 m3 gives way to a refusal, because 150 mm lies below the table''s first entry at 300 mm.", "gross 243.285 m3 gives way to the refusal for water above the product dip."]'::jsonb, 2, 'The water cut goes through the same table as the dip. At 150 mm that table has no entry beneath it, so the water volume cannot be read and the call is refused.'),
  ('supply', 'beginner', 'final', null, 4, 'On AK-02, which step turns 1067.840 m3 into 1054.599 m3?', '["Taking off the 19.101 m3 of free water", "Interpolating between 5250 mm and 5500 mm", "Booking the day''s known losses of 3.100 m3", "Multiplying by the typed VCF of 0.987600"]'::jsonb, 3, '1067.840 m3 is AK-02''s gross observed volume, with the water already off. The typed VCF, read off AKODO''s own invented tables, brings it to 1054.599 m3 at standard.'),
  ('supply', 'beginner', 'final', null, 5, 'What basis must the opening stock and the dipped closing share for reconcileStock''s gap to mean anything?', '["Both are gross observed, since that is the volume the tanks really held.", "The opening is at standard and the closing gross observed, as each was dipped.", "Either basis will do, provided the tolerance percent is raised to cover the gap.", "Both the opening stock and the dipped closing are in m3 at standard."]'::jsonb, 3, 'Closed on the gross 4581.490 m3 against an opening at standard, the day reads unaccounted 73.390 m3, a gain outside tolerance, with nothing in the tanks changed.'),
  ('supply', 'beginner', 'final', null, 6, 'Which of these calls prints one figure and gives another as none?', '["volumeAtDip with no dip", "reconcileStock with no closing dip", "volumeCorrectionFactor with no coefficients", "reconcileStock with no opening stock"]'::jsonb, 1, 'With no closing dip the expected closing, 4508.100 m3, still prints and the unaccounted figure reads none. The other three calls refuse outright.'),
  ('supply', 'beginner', 'final', null, 7, 'The digest straps two AKODO tanks a second time at 10 mm. On which of them does the step change the reading at the dip?', '["AK-03, the bullet", "AK-01, the vertical tank", "Both of them, by the same amount", "Neither of them, to the litre"]'::jsonb, 0, 'AK-01''s 250 mm and 10 mm tables both read 3542.077 m3. On AK-03 the 100 mm table less the 10 mm table is -0.007 m3 at the 1847 mm dip.'),
  ('supply', 'beginner', 'final', null, 8, 'The total gross observed volume of 4581.490 m3 is summed over tanks standing at which temperatures?', '["15 C for all three tanks", "31.5 C, 30 C and 29 C", "10 C, 15 C and 20 C", "35 C, 40 C and 31.5 C"]'::jsonb, 1, 'AK-01 stands at 31.5 C, AK-02 at 30 C and AK-03 at 29 C, and each gross observed volume is at its tank''s temperature. The day is closed on the standard total, 4499.452 m3.'),
  ('supply', 'beginner', 'final', null, 9, 'In the printed tolerance sweep, what is the smallest percent at which the AKODO day reads within tolerance?', '["0.1 percent, a band of 6.183 m3", "0.2 percent, a band of 12.365 m3", "0.05 percent, a band of 3.091 m3", "0.3 percent, a band of 18.547 m3"]'::jsonb, 1, 'The gap is -8.648 m3 in every row. At 0.05 and 0.1 percent the day reads outside the band; the row at 0.2 percent is the first printed as true.'),
  ('supply', 'beginner', 'final', null, 10, 'Two percents of throughput appear in this tier: -0.1399 and -0.0494. What is the denominator of each?', '["55085.000 m3 for the day''s -0.1399, and 6182.500 m3 for the nine days'' -0.0494", "4953.700 m3, the opening stock, for both figures", "6310.000 m3, the latest day''s throughput, for both figures", "6182.500 m3 for the day''s -0.1399, and 55085.000 m3 for the nine days'' -0.0494"]'::jsonb, 3, 'The day''s percent is its gap on its own throughput. The trend''s percent is the cumulative gap, -27.200 m3, on the cumulative throughput, printed as 55085.000 m3.'),
  ('supply', 'beginner', 'final', null, 11, 'On which day does the cumulative unaccounted column first go below zero?', '["day 2", "day 4", "day 9", "day 5"]'::jsonb, 3, 'The running total reads 4.200, 0.600, 2.500 and 0.100 m3 over days 1 to 4, sits below zero from day 5 onward and reaches -27.200 m3 at day 9.'),
  ('supply', 'beginner', 'final', null, 12, 'RATE_DISCLAIMER gives the engine''s reason for shipping no rate. What does it say about duties, levies and regulated margins?', '["They are published once a year, so the engine ships the latest.", "They are fixed by the course, so the user types none of them.", "They are set by regulation, differ by market and change.", "They are typical figures, labelled as a starting point."]'::jsonb, 2, 'The disclaimer names every rate as a required input and tells the user to confirm each one against the regulation in force. The engine ships none, and every rate in this course is invented for it.'),
  ('supply', 'beginner', 'final', null, 13, 'How many rates do the two fuelPricing templates ship?', '["None: 9 of 9 import line items and 7 of 7 pump line items are absent.", "9 import rates and 7 pump rates, each marked for confirmation.", "7 pump rates only, since the import side depends on the cargo.", "One rate per basis in CHARGE_BASIS, and none for the pump."]'::jsonb, 0, 'IMPORT_TEMPLATE carries 9 line items and PUMP_TEMPLATE 7, and the rate shipped column reads none on every row. The templates name charges and bases only.'),
  ('supply', 'beginner', 'final', null, 14, 'fuelPricing.M3_PER_BBL reads 0.158987294928. What kind of figure is it?', '["The m3 in one barrel, a constant the engine ships", "A figure invented for this course", "A typical ratio for petrol, labelled a starting point", "A rate the user must confirm against the regulation"]'::jsonb, 0, 'M3_PER_BBL is one of fuelPricing''s 8 exported constants, beside LITRES_PER_M3 at 1000. It is no rate: both templates ship every rate as none. PRODUCT_REFERENCE is the table labelled a starting point.'),
  ('supply', 'beginner', 'final', null, 15, 'AK-01 is dipped at 125 mm and reads 47.517 m3. Which two entries bracket that dip?', '["125 mm at 47.517 m3, an entry of its own", "0 mm at 0.000 m3 and 250 mm at 95.033 m3", "250 mm at 95.033 m3 and 9250 mm at 3516.228 m3", "0 mm at 0.000 m3 and 300 mm at 114.040 m3"]'::jsonb, 1, 'AK-01''s table steps every 250 mm from the empty tank, so 125 mm lies between its first two entries. The 300 mm entry belongs to the partial calibration.'),
  ('supply', 'beginner', 'final', null, 16, 'A terminal extends its partial calibration down to the tank floor. Which refused rows does that cure?', '["The 700 mm water cut and the -10 mm water cut", "The 14800 mm dip and the 180 mm dip", "The -5 mm dip and the 150 mm water cut", "The 180 mm dip and the 150 mm water cut"]'::jsonb, 3, 'Both refusals end by asking for the table to be extended down to the tank floor, since 180 mm and 150 mm lie below the first entry at 300 mm. The 700 mm cut is above the dip, the -10 mm cut and the -5 mm dip are negative, and 14800 mm is above AK-01''s last entry; each has its own sentence.'),
  ('supply', 'beginner', 'final', null, 17, 'Someone reading the bullet''s table only once, at the product height less the water height, would look up which height?', '["1800 mm", "1806 mm", "1847 mm", "41 mm"]'::jsonb, 1, 'Subtracting heights first gives 1806 mm, which reads 51.126 m3. The engine reads 1847 mm and 41 mm separately and returns the gross 52.161 m3.'),
  ('supply', 'beginner', 'final', null, 18, 'Across the synthetic temperature sweep at 741.6 kg/m3, at which temperature does the VCF sit furthest below one?', '["10 C, at 1.006736", "31.5 C, at 0.977583", "40 C, at 0.965932", "15 C, at 1.000000"]'::jsonb, 2, 'The warmer the product the further below one the synthetic VCF reads, down to 0.965932 at the sweep''s top temperature of 40 C. These coefficients are invented and correct no stock.'),
  ('supply', 'beginner', 'final', null, 19, 'In the two lines of the correction form, where does the density at 15 C enter?', '["In the second line, through dT.", "In both lines equally, as a multiplier on the whole exponent.", "Nowhere, since the density only selects the commodity group.", "In the first line, alpha = K0 / rho^2 + K1 / rho + K2."]'::jsonb, 3, 'Temperature enters the second line alone and density the first alone. That is why alpha reads 0.001350036 across the temperature sweep and moves across the density sweep.'),
  ('supply', 'beginner', 'final', null, 20, 'On the synthetic row at 31.5 C, what does the form print for a density of 846.3 kg/m3?', '["alpha 0.001195545, VCF 0.980162", "alpha 0.001080514, VCF 0.987600", "alpha 0.001350036, VCF 0.977583", "alpha 0.001080514, VCF 0.982080"]'::jsonb, 3, 'The density sweep at 31.5 C prints alpha 0.001080514 and VCF 0.982080 at 846.3 kg/m3. 0.987600 is AK-02''s typed VCF, which does not come from the synthetic row, and the other pairs belong to 796.8 kg/m3 and 741.6 kg/m3.'),
  ('supply', 'beginner', 'final', null, 21, 'AKODO''s typed VCFs are 0.980300, 0.987600 and 0.988400, at 31.5 C, 30 C and 29 C. Which is true of all three?', '["Each is above one, and each tank stands above 15 C.", "Each is below one, and each tank stands above 15 C.", "Each is the synthetic row''s figure at that tank''s density and temperature.", "Each equals one less the tank''s water share at its morning dip."]'::jsonb, 1, 'All three typed figures are below one, and 31.5 C, 30 C and 29 C are all above 15 C. The form''s own invariants are a VCF of exactly 1 at 15 C and below 1 above it. At 741.6 kg/m3 and 31.5 C the synthetic row reads 0.977583, against AK-01''s typed 0.980300.'),
  ('supply', 'beginner', 'final', null, 22, 'A still day reads unaccounted 0.500 m3. Which direction does the engine print?', '["loss", "balanced", "gain", "none"]'::jsonb, 2, 'unaccounted = dipped closing - expected closing, so a positive figure is a gain. With no throughput the tolerance is 0.000 m3 and the day reads within tolerance false.'),
  ('supply', 'beginner', 'final', null, 23, 'Where do AKODO''s known losses of 3.100 m3 enter the day?', '["They are added to receipts and deliveries to form the throughput.", "They are taken off the dipped closing before the gap is read.", "They are taken off in forming the expected closing.", "They widen the tolerance band on the day by their own amount."]'::jsonb, 2, 'expected closing = opening + receipts - deliveries - known losses. Throughput is receipts plus deliveries alone, 6182.500 m3.'),
  ('supply', 'beginner', 'final', null, 24, 'In the demonstration that cannot fail, a closing dip of 4600.000 m3 is used. What expected closing does the ledger give?', '["5045.600 m3", "4600.000 m3", "4508.100 m3", "4499.452 m3"]'::jsonb, 1, 'The opening taken from that dip is 5045.600 m3, and the ledger undoes the derivation exactly, so the expected closing is the dip itself and the gap is 0.000 m3.'),
  ('supply', 'beginner', 'final', null, 25, 'Which of these refusals is about the dip itself, the first link of the AKODO chain?', '["REFUSED: The water cut is above the product dip. Check both readings.", "REFUSED: No opening stock, so the day cannot be closed. The opening stock is yesterday''s closing dip.", "REFUSED: A dip cannot be negative.", "REFUSED: Density at 15 C and observed temperature are both needed."]'::jsonb, 2, 'A dip of -5 mm is refused because a dip cannot be negative. The other sentences belong to the water cut, the day and the correction.'),
  ('supply', 'beginner', 'final', null, 26, 'Which description matches AK-01''s strapping table?', '["60 entries every 250 mm, from 0 mm to 14750 mm", "49 entries every 250 mm, from 0 mm to 12000 mm", "31 entries every 100 mm, from 0 mm to 3000 mm", "60 entries every 250 mm, from 300 mm to 800 mm"]'::jsonb, 0, 'AK-01 is 22 m in diameter and strapped to 14750 mm, where it reads 5606.957 m3. The 49 entry table is AK-02''s and the 31 entry table AK-03''s.'),
  ('supply', 'beginner', 'final', null, 27, 'With no days of history, which of trendUnaccounted''s three figures reads none?', '["The cumulative", "The run", "The mean percent", "All three of them"]'::jsonb, 2, 'With no days the engine prints cumulative 0.000 m3, run 0 and mean percent none. Two of the three are figures at zero, and only the percent, whose denominator is the cumulative throughput, reads none.'),
  ('supply', 'beginner', 'final', null, 28, 'In the trimmed record, what is the shortest run of loss the digest shows printing the prompt?', '["3 days of loss", "6 days of loss", "4 days of loss", "2 days of loss"]'::jsonb, 2, 'The trimmed table is the only evidence: its row for 6 kept days shows 3 days of loss with no prompt, and its row for 7 kept days shows 4 days with the prompt.'),
  ('supply', 'beginner', 'final', null, 29, 'When a cost or price build-up is called with rates left out, how does the price module answer?', '["It refuses the call until every rate in the template is typed.", "It fills each missing rate with zero and reports a finished total.", "It labels the build-up incomplete and counts the missing rates.", "It fills each missing rate from PRODUCT_REFERENCE''s starting points."]'::jsonb, 2, 'This is the third shape of answer, met in the Expert tier. A partial total is never read as a finished one.'),
  ('supply', 'beginner', 'final', null, 30, 'AKODO''s tank figures come in three kinds: at the dip, gross observed and standard. Which kind is 4499.452 m3?', '["Standard, the total the day is closed on", "Gross observed, the total with the water off", "At the dip, the total with the water in", "Expected, the ledger''s closing"]'::jsonb, 0, '4499.452 m3 is the total standard volume, the closing stock the day is closed on. The gross observed total is 4581.490 m3 and the expected closing 4508.100 m3.'),
  ('supply', 'beginner', 'final', null, 31, 'The gross observed volume and the standard volume each remove something from the volume at the dip. What does each remove?', '["The gross removes free water; the standard volume then removes the effect of temperature.", "The gross removes the effect of temperature; the standard volume then removes free water.", "The gross removes free water; the standard volume removes the day''s known losses.", "Both remove free water, read once at the dip and once again at the reference."]'::jsonb, 0, 'On AK-01, 3542.077 m3 at the dip less 80.588 m3 of water is 3461.489 m3 gross observed, and the typed 0.980300 brings that to 3393.298 m3 at standard.'),
  ('supply', 'beginner', 'final', null, 32, 'The tolerance percent is swept on the AKODO day from 0.05 to 0.5. Which figure is the same in every row?', '["The band, 12.365 m3", "The unaccounted figure, -8.648 m3", "The verdict, within tolerance true", "The percent itself, 0.2 of throughput"]'::jsonb, 1, 'The sweep is on the same day, so the unaccounted figure stays -8.648 m3. The band runs from 3.091 m3 to 30.913 m3, and the verdict is false at 0.05 and 0.1 percent and true from 0.2 percent.'),
  ('supply', 'beginner', 'final', null, 33, 'How many functions and constants does fuelPricing export?', '["8 functions and 0 constants", "8 functions and 9 constants", "9 functions and 0 constants", "9 functions and 8 constants"]'::jsonb, 3, 'terminalDepot exports 8 functions and 0 constants. fuelPricing''s 8 constants include the two templates, the disclaimer and the two conversions.'),
  ('supply', 'beginner', 'final', null, 34, 'AK-02 is dipped at 5406 mm with 400 mm of water. What gross observed volume does the engine return?', '["1086.941 m3", "1067.840 m3", "80.425 m3", "1006.516 m3"]'::jsonb, 3, 'The water at 400 mm reads 80.425 m3 through AK-02''s table and comes off the volume at the dip, 1086.941 m3, leaving a gross of 1006.516 m3.'),
  ('supply', 'beginner', 'final', null, 35, 'Trace AK-01''s standard volume of 3393.298 m3 back one link. Which two figures does it rest on?', '["3542.077 m3 at the dip and a typed VCF of 0.980300", "3461.489 m3 and a VCF built from K0 = 520, K1 = 0.3 and K2 = 0", "3461.489 m3 gross observed and a typed VCF of 0.980300", "4499.452 m3 in total and AK-01''s share of the three tanks"]'::jsonb, 2, 'standard volume = gross observed volume x VCF. The gross already has the water off, and the VCF is typed off AKODO''s own tables; the synthetic row corrects no stock.'),
  ('supply', 'beginner', 'final', null, 36, 'AK-01 is dipped at exactly 9500 mm. What does volumeAtDip return?', '["3611.261 m3, the entry''s own volume", "3542.077 m3, interpolated from 9318 mm", "3516.228 m3, the entry below the dip", "A refusal, since a dip must fall between two entries"]'::jsonb, 0, 'When a dip lands on an entry the engine returns that entry''s volume. At 9318 mm it interpolates between 9250 mm and 9500 mm.'),
  ('supply', 'beginner', 'final', null, 37, 'What direction does reconcileStock print for a day with throughput whose unaccounted figure is 0.000 m3?', '["loss", "gain", "none", "balanced"]'::jsonb, 3, 'Each row of the derived demonstration reads unaccounted 0.000 m3, within tolerance true, direction balanced. A balanced day built that way measured nothing.'),
  ('supply', 'beginner', 'final', null, 38, 'What water volume does the engine read for AK-01''s water cut of 212 mm?', '["80.588 m3", "19.101 m3", "80.425 m3", "0.341 m3"]'::jsonb, 0, 'AK-01''s 212 mm cut goes through its own table and reads 80.588 m3. 19.101 m3 is AK-02''s water at 95 mm, 80.425 m3 AK-02''s at 400 mm and 0.341 m3 AK-03''s at 41 mm.'),
  ('supply', 'beginner', 'final', null, 39, 'The demonstration that cannot fail is given AKODO''s own closing dip, 4499.452 m3. What opening stock does it derive?', '["4945.052 m3", "4953.700 m3", "4508.100 m3", "5045.600 m3"]'::jsonb, 0, 'Taken as closing dip - receipts + deliveries + known losses, the opening from 4499.452 m3 is 4945.052 m3, and the day then balances at 0.000 m3. 4953.700 m3 is the real opening, yesterday''s closing dip, and 5045.600 m3 is derived from a dip of 4600.000 m3.'),
  ('supply', 'beginner', 'final', null, 40, 'What makes a table''s first and last entries the edges of any stock figure from that tank?', '["The engine extrapolates beyond them but flags the result as uncertified.", "The first entry is always the empty tank and the last the full one.", "The engine interpolates between them and refuses below the first and above the last.", "The terminal sets them to its safe working range for each product."]'::jsonb, 2, 'A strapping table is trusted over the heights it covers and nowhere else. The partial table starting at 300 mm shows that a first entry need not be the empty tank.'),
  ('supply', 'beginner', 'final', null, 41, 'PRODUCT_REFERENCE lists DPK at a typical 800 kg/m3, and AK-03''s kerosene was measured at 796.8 kg/m3. Which figure goes into AK-03''s VCF lookup?', '["796.8 kg/m3, the measured density", "800 kg/m3, the reference figure", "Whichever lies nearer the range midpoint", "Neither, since a typed VCF needs no density"]'::jsonb, 0, 'Nothing reads the reference unless a caller passes it in. AKODO reads its VCF of 0.988400 off its own tables for the measured 796.8 kg/m3 and 29 C.'),
  ('supply', 'beginner', 'final', null, 42, 'How does the closing dip of one AKODO day relate to the opening stock of the next?', '["The opening is the closing dip corrected a second time to standard the next morning.", "They are one figure: the opening stock is yesterday''s closing dip.", "The opening is the closing dip less the known losses booked overnight.", "The opening is the expected closing, 4508.100 m3, carried forward."]'::jsonb, 1, 'reconcileStock''s own refusal says so: the opening stock is yesterday''s closing dip. That is why the AKODO day opens on 4953.700 m3.');
